import json
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

PIECES = "social_content_pieces"
PREFERRED_DAYS = [1, 2, 3, 0, 4]  # Tue, Wed, Thu, then Mon, Fri


def text(value):
    if value is None:
        return ""
    return str(value).strip()


def as_list(value):
    if isinstance(value, list):
        return [str(v).strip() for v in value if str(v).strip()]
    return [part.strip() for part in text(value).replace(",", chr(10)).splitlines() if part.strip()]


settings = api.extension.settings() or {}
folder = text(settings.get("knowledge_folder")) or "Social posts"
zone = ZoneInfo(text(settings.get("time_zone")) or "Australia/Sydney")
try:
    target = int(settings.get("posts_per_week") or 0)
except (TypeError, ValueError):
    target = 0
target = max(0, min(target, 14))

today = datetime.now(zone).date()
week_start = today - timedelta(days=today.weekday()) + timedelta(days=7)  # next Monday
week_end = week_start + timedelta(days=6)

created = 0
existing = 0
planned = 0
skipped_reason = ""
new_titles = []

if target == 0:
    skipped_reason = "Posts per week is not set, so the rhythm top-up is off."
else:
    try:
        brand = json.loads(api.files.read(file=f"{folder}/Brand Kit/brand-kit.json"))
    except Exception:
        brand = {}
    messages = as_list(brand.get("key_messages")) or as_list(brand.get("services"))
    if not brand.get("company_name"):
        skipped_reason = "There is no confirmed Brand Kit yet."
    else:
        rows = []
        cursor = None
        for _ in range(10):
            page = api.records.list(type_slug=PIECES, limit=200, cursor=cursor) or {}
            rows.extend(page.get("records") or [])
            cursor = page.get("nextCursor")
            if not cursor:
                break
        taken = set()
        for row in rows:
            raw = text((row.get("data") or {}).get("publish_date"))[:10]
            try:
                when = date.fromisoformat(raw)
            except ValueError:
                continue
            if week_start <= when <= week_end:
                planned += 1
                taken.add(when)
        missing = max(0, target - planned)
        free = [week_start + timedelta(days=d) for d in PREFERRED_DAYS if week_start + timedelta(days=d) not in taken]
        # More posts than free weekdays: reuse days in the same order.
        slots = (free or [week_start + timedelta(days=d) for d in PREFERRED_DAYS])
        week_number = week_start.isocalendar()[1]
        for n in range(missing):
            day = slots[n % len(slots)]
            message = messages[(week_number + n) % len(messages)] if messages else text(brand.get("company_name"))
            title = message[:180]
            data = {
                "content_type": "social_post",
                "origin": "rhythm",
                "publish_date": day.isoformat(),
                "topic": message[:200],
                "angle": "Always-on post built around this Brand Kit key message. Make one practical point a small business can use this week.",
                "brief": f"Rhythm top-up: keep {target} posts a week on the calendar.",
                "generate_draft": True,
                "piece_key": f"rhythm:{week_start.isoformat()}:{n + 1}",
            }
            try:
                api.records.create(type_slug=PIECES, record={"title": title, "stage": "planned", "data": data})
                created += 1
                new_titles.append(day.strftime("%a %d/%m") + ": " + title)
            except Exception as error:
                # The piece key is unique: a re-run in the same week is refused, not duplicated.
                if "unique" in str(error).lower():
                    existing += 1
                else:
                    raise

week = week_start.strftime("%d/%m") + " to " + week_end.strftime("%d/%m/%Y")
